class Solution {
    public int minPathSum(int[][] grid) {
        int n=grid[0].length;int[] dp=new int[n];Arrays.fill(dp,Integer.MAX_VALUE);dp[0]=0;
        for(int[] row:grid)for(int c=0;c<n;c++){int left=c>0?dp[c-1]:Integer.MAX_VALUE;dp[c]=row[c]+Math.min(dp[c],left);}
