class Solution:
    def simplifyPath(self, path: str) -> str:
        stack=[]
        for part in path.split('/'):
            if part=='' or part=='.':continue
            if part=='..':
                if stack:stack.pop()
            else:stack.append(part)
        return '/'+'/'.join(stack)

import java.util.*;

class Solution {
    public String simplifyPath(String path) {
        Deque<String> stack=new ArrayDeque<>();
        for(String part:path.split("/")){if(part.isEmpty()||part.equals("."))continue;if(part.equals("..")){if(!stack.isEmpty())stack.removeLast();}else stack.addLast(part);}
        return "/"+String.join("/",stack);
    }
}

class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        m,n=len(word1),len(word2);dp=[[0]*(n+1) for _ in range(m+1)]
        for i in range(m+1):dp[i][0]=i
        for j in range(n+1):dp[0][j]=j
        for i in range(1,m+1):
            for j in range(1,n+1):
                if word1[i-1]==word2[j-1]:dp[i][j]=dp[i-1][j-1]
                else:dp[i][j]=1+min(dp[i-1][j],dp[i][j-1],dp[i-1][j-1])
        return dp[m][n]

class Solution {
    public int minDistance(String a,String b) {
        int m=a.length(),n=b.length();int[][]dp=new int[m+1][n+1];for(int i=0;i<=m;i++)dp[i][0]=i;for(int j=0;j<=n;j++)dp[0][j]=j;
        for(int i=1;i<=m;i++)for(int j=1;j<=n;j++){if(a.charAt(i-1)==b.charAt(j-1))dp[i][j]=dp[i-1][j-1];else dp[i][j]=1+Math.min(dp[i-1][j],Math.min(dp[i][j-1],dp[i-1][j-1]));}
