        m,n=len(matrix),len(matrix[0]);first_row=any(x==0 for x in matrix[0]);first_col=any(matrix[r][0]==0 for r in range(m))
        for r in range(1,m):
            for c in range(1,n):
                if matrix[r][c]==0:matrix[r][0]=matrix[0][c]=0
        for r in range(1,m):
            for c in range(1,n):
                if matrix[r][0]==0 or matrix[0][c]==0:matrix[r][c]=0
        if first_row:matrix[0]=[0]*n
        if first_col:
            for r in range(m):matrix[r][0]=0

class Solution {
    public void setZeroes(int[][] a) {
        int m=a.length,n=a[0].length;boolean fr=false,fc=false;for(int c=0;c<n;c++)if(a[0][c]==0)fr=true;for(int r=0;r<m;r++)if(a[r][0]==0)fc=true;
        for(int r=1;r<m;r++)for(int c=1;c<n;c++)if(a[r][c]==0){a[r][0]=0;a[0][c]=0;}
        for(int r=1;r<m;r++)for(int c=1;c<n;c++)if(a[r][0]==0||a[0][c]==0)a[r][c]=0;
        if(fr)Arrays.fill(a[0],0);if(fc)for(int r=0;r<m;r++)a[r][0]=0;
    }
}

