class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        m,n=len(matrix),len(matrix[0]);left,right=0,m*n-1
        while left<=right:
            mid=(left+right)//2;value=matrix[mid//n][mid%n]
            if value==target:return True
            if value<target:left=mid+1
            else:right=mid-1
        return False

class Solution {
    public boolean searchMatrix(int[][] a,int target) {
        int m=a.length,n=a[0].length,l=0,r=m*n-1;while(l<=r){int mid=l+(r-l)/2,v=a[mid/n][mid%n];if(v==target)return true;if(v<target)l=mid+1;else r=mid-1;}return false;
    }
}

