        int low=0,cur=0,high=nums.length-1;while(cur<=high){if(nums[cur]==0){int t=nums[low];nums[low++]=nums[cur];nums[cur++]=t;}else if(nums[cur]==2){int t=nums[cur];nums[cur]=nums[high];nums[high--]=t;}else cur++;}
    }
}

