class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not t or len(t)>len(s):return ""
        need=Counter(t);have={};formed=0;required=len(need);left=0;best=(float('inf'),0,0)
        for right,ch in enumerate(s):
            have[ch]=have.get(ch,0)+1
            if ch in need and have[ch]==need[ch]:formed+=1
            while formed==required:
                if right-left+1<best[0]:best=(right-left+1,left,right+1)
                drop=s[left];have[drop]-=1
                if drop in need and have[drop]<need[drop]:formed-=1
                left+=1
        return "" if best[0]==float('inf') else s[best[1]:best[2]]

import java.util.*;

class Solution {
    public String minWindow(String s,String t) {
        if(t.isEmpty()||t.length()>s.length())return "";Map<Character,Integer>need=new HashMap<>(),have=new HashMap<>();for(char c:t.toCharArray())need.merge(c,1,Integer::sum);
        int formed=0,left=0,bestLen=Integer.MAX_VALUE,bestL=0,required=need.size();
        for(int right=0;right<s.length();right++){char c=s.charAt(right);have.merge(c,1,Integer::sum);if(need.containsKey(c)&&have.get(c).intValue()==need.get(c).intValue())formed++;
            while(formed==required){if(right-left+1<bestLen){bestLen=right-left+1;bestL=left;}char d=s.charAt(left++);have.put(d,have.get(d)-1);if(need.containsKey(d)&&have.get(d)<need.get(d))formed--;}
        }
        return bestLen==Integer.MAX_VALUE?"":s.substring(bestL,bestL+bestLen);
    }
}

